typedef struct io_quota {
  atomic_long tokens;
  long refill_rate; // tokens/ms
  wait_queue_t *wait;
} io_quota_t;

bool submit_io(io_task_t *t, size_t bytes) {
  long old = atomic_fetch_sub(&t->quota->tokens, bytes);
  if (old >= (long)bytes) return true; // enough tokens
  atomic_fetch_add(&t->quota->tokens, bytes); // revert
  enqueue_wait(t->quota->wait, t);
  return false;
}
